import {educationBadges,opportunitiesPanel} from './career-opportunities-ui.js';
import {applyFictionalInterestProfile} from './fictional-interest-profiles.js?v=0.31.0';
import {pathwayProfileQuestions} from './pathway-profile-bank.js?v=0.31.0';
import {profileInterestQuestions,profileInterestAnswer} from './profile-interest-bank.js?v=0.31.0';
import {freshState,escapeHTML as h} from './model.js?v=0.31.0';
import {studentExamples} from './student-examples.js?v=0.31.0';
import {curiosity,priorities} from './content.js?v=0.31.0';
import {profileQuestions,skillQuestions,contextQuestions,broadSuggestions,professionSuggestions,makeJourneyPlan} from './profile-journey.js?v=0.31.0';
import {professionQuestions} from './profession-questions.js?v=0.31.0';
import {buildLifestyleInputs,lifestyleChoices} from './lifestyle-builder.js?v=0.31.0';
import {fieldGlyph} from './profile-journey-ui.js?v=0.31.0';
import {occupationById} from './occupation-data.js?v=0.31.0';
import {salaryPreviewStages,formatSalary} from './salary-progression.js?v=0.31.0';
import {lifestyleRoom,lifestyleIncomeRange} from './lifestyle-story.js?v=0.31.0';
import {clinicalTrainingTimeline,professionalCostPanel,graduateAidPanel} from './education-evidence-ui.js?v=0.31.0';
import {trainingCostPreview} from './profile-ui.js?v=0.31.0';
import {preparationPreview} from './planning-guidance.js?v=0.31.0';
import {educationCostsPanel} from './context-ui.js?v=0.31.0';
import {salaryPanel} from './salary-ui.js?v=0.31.0';

export const journeyWalkthroughs=[
 {id:'medicine',family:'health',chosen:'physician',choices:['health-care-1','health-investigate-1','health-support-1','health-workday-1','health-refine-1-1','health-refine-2-1','health-refine-3-1','health-refine-4-1','health-role-work-physician','health-role-observe-physician','health-role-learning-physician'],skills:['reasoning','words','people'],why:'This student chooses family medicine after comparing several clinical roles. The student prefers a physician’s diagnostic work and medical-school/residency preparation. Related nursing and PA routes stay available to compare.'},
 {id:'creative',family:'creative',chosen:'graphic-design',choices:['creative-make-1','creative-revise-1','creative-people-1','creative-workday-1','creative-refine-1-1','creative-refine-2-1','creative-refine-3-1','creative-refine-4-1'],skills:['visual','words','digital'],why:'This student chooses graphic design after comparing it with digital interface design. Only the supported design pathway is featured; other fields remain available as choices. Visual layouts alone do not imply an interest in public relations.'},
 {id:'trades',family:'trades',chosen:'electrician',choices:['trades-systems-1','trades-process-2','trades-place-2','trades-workday-1','trades-refine-1-1','trades-refine-2-1','trades-refine-3-1','trades-refine-4-1'],skills:['practical','visual','reasoning'],why:'Wiring and circuits make electrical work the strongest task connection. Plumbing shares enough installation and work-site interests to stay on the shortlist. HVAC remains available in the full field list.'}
];
// These are scripted fictional choices, not observed student outcomes or a validity study.
export function walkthroughState(id,{plan=false,answers=true}={}){const spec=journeyWalkthroughs.find(x=>x.id===id)||journeyWalkthroughs[0],e=studentExamples.find(x=>x.id===spec.id),s=freshState();s.profile.nickname='Fictional '+e.title+' student';s.guide.entry='assessment';s.profileJourney.started=true;if(!answers)return s;
const builder=s.guide.lifestyleBuilder;builder.choices=Object.fromEntries(lifestyleChoices.map(c=>[c.id,['home','transport'].includes(c.id)?2:1]));builder.complete=true;s.guide.lifestylePreset='custom';s.finance.lifestyle=buildLifestyleInputs(builder,s.finance.lifestyle);
applyFictionalInterestProfile(s,spec.id);
const focused={medicine:{health:[5,5,4],science:[4,4,4],education:[4,3,4]},creative:{creative:[5,5,5]},trades:{trades:[5,5,5],building:[3,3,3],'transportation-production':[4,4,4]}}[spec.id];for(const q of pathwayProfileQuestions)s.profileJourney.fieldPreferences[q.id]=focused[q.family]?.[['activity','setting','routine'].indexOf(q.facet)]??2;
s.priorities=[...e.priorities];s.profileJourney.answers.values=true;
for(const q of skillQuestions)s.profileJourney.skills[q.id]={level:spec.skills.includes(q.id)?'supported':'new'};
Object.assign(s.profileJourney.answers,{company:'team',rhythm:'variety',setting:spec.id==='trades'?['active']:spec.id==='medicine'?['people','desk']:['desk'],education:spec.id==='medicine'?['college','graduate']:spec.id==='creative'?['college']:['training','college']});
s.profileJourney.index=profileQuestions.length-1;s.profileJourney.family=spec.family;s.profileJourney.families=[spec.family];s.profileJourney.suggestedFamilies=broadSuggestions(s).fields.map(f=>f.id);s.profileJourney.depth[spec.family]=Object.fromEntries(professionQuestions[spec.family].map(q=>[q.id,q.options.filter(o=>spec.choices.includes(o.id)).map(o=>o.id)]));s.profileJourney.depthIndexes[spec.family]=7;
if(plan)makeJourneyPlan(s,spec.chosen);return s;}
export function walkthroughResult(id){const spec=journeyWalkthroughs.find(x=>x.id===id)||journeyWalkthroughs[0],s=walkthroughState(spec.id,{plan:true}),pathways=broadSuggestions(s),professions=professionSuggestions(s),room=lifestyleRoom(s.finance.lifestyle),range=lifestyleIncomeRange(s.finance.lifestyle);return {spec,s,pathways,professions,room,range};}
export function journeyWalkthroughPage(id='medicine'){const {spec,s,pathways,professions,room,range}=walkthroughResult(id),e=studentExamples.find(x=>x.id===spec.id),o=occupationById(spec.chosen),stages=salaryPreviewStages(o.id),start=stages.find(x=>x.key===s.guide.salaryStage);return `<div class="page-intro"><div><span class="eyebrow">THE NEW GUIDE · FICTIONAL WALKTHROUGHS</span><h1>Three students. Three different plans.</h1><p>Read-only examples. Your own answers and plan stay yours.</p></div></div><nav class="salary-preview-stages" aria-label="Example students">${journeyWalkthroughs.map(x=>`<a href="#/student-examples/${x.id}" ${x.id===spec.id?'aria-current="page"':''}>${h(studentExamples.find(e=>e.id===x.id).title)}</a>`).join('')}</nav><section class="guide-input-panel"><p><a href="./developer/students/walkthrough-${h(spec.id)}.html">Expanded view →</a> · All questions, answers & results</p><h2>What draws this student in?</h2><p>${h(e.reflection)}</p><p>They like ${spec.id==='medicine'?'investigating illness, explaining science, and helping patients':spec.id==='creative'?'visual ideas, layouts, and revising a design after feedback':'hands-on troubleshooting, safe installation, and working electrical systems'}.</p><p>Confidence is modest. It does not raise or lower their interest suggestions.</p></section><h2>Their supported pathways</h2><div class="pathway-trio">${pathways.fields.map(f=>`<article class="pathway-card ${f.supported?'pathway-supported':''}">${fieldGlyph(f.id)}<span class="card-kicker">${f.supported?'Profile connections':'Related option · not a personal match'}</span><h3>${h(f.title)}</h3>${f.supported?'<b>Your pattern across answers</b><ul class="pathway-pattern-list">'+f.reasons.map(t=>'<li>'+h(t)+'</li>').join('')+'</ul>':'<p>An adjacent field to compare. No direct personal match is claimed.</p>'}</article>`).join('')}</div><section class="guide-input-panel"><h2>Then, focused questions about ${h(e.title.toLowerCase())}.</h2><p>These are the roles connected by at least three different answers:</p><div class="tags">${professions.top.map(r=>`<span class="tag">${h(r.o.finance?.title||r.o.title)}</span>`).join('')}</div><p>${h(spec.why)}</p><details class="more-info"><summary>See the follow-up choices</summary>${professionQuestions[spec.family].map(q=>`<p><strong>${h(q.prompt)}</strong><br>${q.options.filter(x=>spec.choices.includes(x.id)).map(x=>h(x.text)).join(' · ')}</p>`).join('')}</details></section><section class="guide-input-panel"><span class="eyebrow">THE STUDENT’S CHOICE · THEIR PERSONAL PLAN</span><h2>${h(o.finance?.title||o.title)}</h2>${educationBadges(o)}<p>${h(s.guide.preparation)}</p><p>${h(preparationPreview(o.id)||o.finance?.requirements.typicalEntry||'')}</p>${clinicalTrainingTimeline(o.id)}<p>${h(e.watch)}</p></section><section class="guide-input-panel example-reality ${room.key}"><h2>The same Austin lifestyle. Different starting points.</h2><p>One adult. Their own one-bedroom apartment. A reliable used car. One dinner out a week, a simple getaway, regular hobbies, and steady savings.</p><div class="guide-fact-grid"><article><b>${formatSalary(range.low)}–${formatSalary(range.high)}</b><p>Before-tax income target for these choices</p></article><article><b>${formatSalary(start.amount)}</b><p>${h(start.label)} / year before tax</p></article></div><h3>${h(room.title)}</h3><p>${h(room.copy)}</p><p>${start.estimate?'Starting pay is an estimate, not a guaranteed first-job offer.':o.id==='physician'?'Dell Med’s published first-year residency example. College and medical school come before this paid stage.':'One Austin apprenticeship’s published starting schedule, assuming full-time paid hours. It is not a regional average.'} Student-loan payments are not included in this example.</p>${['creative','trades'].includes(spec.id)?'<p>Starting pay does not cover every choice in this picture. Shared housing, a smaller transport budget, or later earnings could help. The plan keeps this gap visible.</p>':'<p>Residency leaves limited room. Loan payments could make this picture too tight. Qualified physician practice pay comes later.</p>'}<details class="more-info"><summary>Pay over time and the lifestyle each salary supports</summary><p>These links open general Austin salary illustrations in the independent library.</p>${salaryPanel(o.id,{stage:s.guide.salaryStage}).replaceAll('#/salary/','#/learn/salary/')}</details></section><details class="more-info"><summary>College costs and ways to pay</summary>${educationCostsPanel(s,o.id).replace(/<a class="button secondary" href="#\/money">[\s\S]*?<\/a>/,'')}</details>${trainingCostPreview(o.id)}${professionalCostPanel(o.id)}${graduateAidPanel(o.id)}<section class="guide-input-panel">${opportunitiesPanel(s,{anchorId:o.id,compact:true,informationOnly:true})}<h2>Their next three steps</h2>${s.actions.filter(a=>a.careerId===o.id).map((a,i)=>`<article><h3>${i+1}. ${h(a.title)}</h3><p>${h(a.detail)}</p></article>`).join('')}</section><details class="more-info"><summary>Exact profile answers</summary>${profileInterestQuestions.map(q=>`<p><strong>${h(profileInterestAnswer(s,q))} / 5</strong> · ${h(q.text)}</p>`).join('')}${pathwayProfileQuestions.map(q=>`<p><strong>${h(s.profileJourney.fieldPreferences[q.id])} / 5</strong> · ${h(q.prompt)}</p>`).join('')}<p>Each skill activity uses one experience choice. These examples describe needing help or being new to the activity; no ability is inferred.</p></details><details class="more-info"><summary>What these walkthroughs verify</summary><p>Pathways and profession suggestions are calculated from the current guide’s answers. The final career is an explicit fictional student choice. No free text is scored, no aptitude is inferred, and no college admission or career success is predicted. These are behavior checks, not evidence of predictive validity.</p></details>`;}
